css_util:
.overline {
  font-size: 0.75rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--gold);
}
.text-gold { color: var(--gold); }
.bg-emerald { background: var(--emerald); }
.bg-cream { background: var(--cream); color: var(--emerald); }
.text-cream { color: var(--cream); }
.text-muted-dark { color: var(--muted-dark); }
.text-muted-light { color: var(--muted-light); }

.text-gold-gradient {
  background: linear-gradient(120deg, #b8901f 0%, #d4af37 40%, #f0d97a 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

css_nav:
.navbar-custom {
  transition: background-color 0.3s ease, backdrop-filter 0.3s ease;
  background: #0A2A22;
  z-index: 1030;
}
.navbar-custom.scrolled {
  background: rgba(249, 248, 246, 0.9);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(10, 42, 34, 0.1);
}
.navbar-custom .nav-link {
  color: rgba(249, 248, 246, 0.9);
  font-weight: 500;
  font-size: 0.78rem;
  white-space: nowrap;
  padding-inline: 0.4rem;
  transition: color 0.2s ease;
}
.navbar-custom .navbar-nav { flex-wrap: nowrap; }
.navbar-custom.scrolled .nav-link { color: var(--muted-dark); }
.navbar-custom .nav-link:hover { color: var(--gold); }
/* Keep nested hotel menus usable and visible above the page content. */
.navbar-custom .dropdown-menu { z-index: 1050; }
.hotel-dropdown .dropdown-submenu { position: relative; }
.hotel-dropdown .dropdown-submenu > .dropdown-menu {
  top: 0;
  left: 100%;
  margin-top: 0;
}

css_smb:
.side-menu-btn {

  width: 46px;
  height: 46px;

  border: 1px solid #ddd;

  background: #ffffff;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 4px;

  cursor: pointer;

  transition: 0.3s;
}


.side-menu-btn i {

  font-size: 25px;

  color: #222;
}


.side-menu-btn:hover {

  background: #b08a3c;

  border-color: #b08a3c;
}


.side-menu-btn:hover i {

  color: #ffffff;
}


