js_scroll:
// ---- Navbar scroll ----
      const navbar = document.getElementById("navbar");
      const onScroll = () => navbar.classList.toggle("scrolled", window.scrollY > 24);
      window.addEventListener("scroll", onScroll);
      onScroll();

      // Close mobile menu on navigation, but leave dropdown toggles interactive.
      document.querySelectorAll("#navMenu a").forEach((a) =>
        a.addEventListener("click", () => {
          if (a.matches('[data-bs-toggle="dropdown"], .dropdown-submenu > .dropdown-toggle')) return;
          const menu = document.getElementById("navMenu");
          if (menu.classList.contains("show")) new bootstrap.Collapse(menu).hide();
        })
      );

      // Bootstrap handles top-level menus; this handler toggles nested hotel locations.
      document.querySelectorAll(".dropdown-submenu > .dropdown-toggle").forEach((toggle) => {
        toggle.addEventListener("click", (event) => {
          event.preventDefault();
          event.stopPropagation();

          const submenu = toggle.nextElementSibling;
          const shouldOpen = !submenu.classList.contains("show");
          const parentMenu = toggle.closest(".hotel-dropdown");
          parentMenu.querySelectorAll(".dropdown-submenu > .dropdown-menu.show").forEach((openMenu) => {
            openMenu.classList.remove("show");
            openMenu.previousElementSibling.setAttribute("aria-expanded", "false");
          });
          if (shouldOpen) {
            submenu.classList.add("show");
            toggle.setAttribute("aria-expanded", "true");
          } else {
            toggle.setAttribute("aria-expanded", "false");
          }
        });
      });

      // Close any open location submenu when its parent hotel dropdown closes.
      document.getElementById("mainHotelMenu").closest(".dropdown").addEventListener("hidden.bs.dropdown", () => {
        document.querySelectorAll("#mainHotelMenu .dropdown-menu.show").forEach((submenu) => {
          submenu.classList.remove("show");
          submenu.previousElementSibling.setAttribute("aria-expanded", "false");
        });
      });

      // ---- Reveal on scroll ----
      if ("IntersectionObserver" in window) {
      const io = new IntersectionObserver(
        (entries) => {
          entries.forEach((e) => {
            if (e.isIntersecting) {
              e.target.classList.add("visible");
              io.unobserve(e.target);
            }
          });
        },
        { threshold: 0.12 }
      );
      document.querySelectorAll(".reveal").forEach((el) => io.observe(el));
      } else {
        document.querySelectorAll(".reveal").forEach((el) => el.classList.add("visible"));
      }
    </script>
